client_id = params["client_id"] or ""
emp_records = api.employees.list(client_id=client_id)
users = api.users.list()
users_by_id = {u.get("id"): u for u in users}
employees = []
for rec in emp_records:
    uid = rec.get("user_id") or ""
    u = users_by_id.get(uid) or {}
    employees.append({"user_id": uid, "name": u.get("name") or u.get("email") or "", "email": u.get("email") or ""})
